122	// upgradeWebSocket hijacks the connection and writes the 101 response. Every
123	// precondition (method, cursor, session, permission, handshake headers) has
124	// already been checked by the caller; from here on failures are reported as
125	// WebSocket close frames rather than HTTP statuses.
126	func upgradeWebSocket(w http.ResponseWriter, r *http.Request) (*wsConn, error) {
127		hj, ok := w.(http.Hijacker)
128		if !ok {
129			return nil, errors.New("connection does not support hijacking")
130		}
131		conn, brw, err := hj.Hijack()
132		if err != nil {
133			return nil, err
134		}
