371	type wsProtocolErrorString struct{ msg string }
372	
373	func (e *wsProtocolErrorString) Error() string { return "websocket protocol error: " + e.msg }
374	
375	func wsProtocolError(msg string) error { return &wsProtocolErrorString{msg: msg} }
