229	// prefix /v1/documents//); other odd paths there retain their old response so
230	// the pre-existing surface is unchanged. The new device/session families are
231	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
232	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
233	func emptyIDGuard(next http.Handler) http.Handler {
234		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
235			p := r.URL.Path
