338	// decodeJSONBody enforces the strict POST contract shared by every JSON
339	// endpoint: Content-Type must be application/json, the body is capped at
340	// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
341	// may follow it. Any violation writes a 400 JSON error and returns false; the
342	// caller returns immediately, so no handler reaches the store with malformed
343	// input and rejected requests write nothing.
344	func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
345		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
346		if err != nil || mediaType != "application/json" {
347			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
348			return false
349		}
350	
351		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
352		dec := json.NewDecoder(r.Body)
353		if err := dec.Decode(dst); err != nil {
354			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
355			return false
356		}
357		// Reject trailing data after the JSON value.
358		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
359			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
360			return false
361		}
362		return true
363	}
