429	func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
430		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
431	
432		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
433		if err != nil || mediaType != "application/json" {
434			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
435			return
436		}
437	
438		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
439		var req postRequest
440		dec := json.NewDecoder(r.Body)
441		if err := dec.Decode(&req); err != nil {
442			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
443			return
444		}
445		// Reject trailing data after the JSON object.
446		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
447			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
448			return
449		}
450	
451		if req.DeviceID == "" {
452			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
453			return
454		}
455		if len(req.Changes) == 0 {
456			writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
457			return
458		}
459	
460		changes := make([]store.Change, len(req.Changes))
461		seen := make(map[string]struct{}, len(req.Changes))
462		for i, c := range req.Changes {
463			if c.ID == "" {
464				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
465				return
466			}
467			if len(c.Payload) == 0 {
468				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
469				return
470			}
471			if _, dup := seen[c.ID]; dup {
472				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
473				return
474			}
475			seen[c.ID] = struct{}{}
476			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
477		}
478	
479		results, err := s.PostChanges(documentID, changes)
480		if err != nil {
481			var conflict *store.ErrConflict
482			if errors.As(err, &conflict) {
483				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
484				return
485			}
486			writeError(w, http.StatusInternalServerError, "failed to commit changes")
487			return
488		}
489	
490		writeJSON(w, http.StatusOK, map[string]any{"results": results})
491	}
