493	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
494		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
495	
496		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
497		if err != nil || mediaType != "application/json" {
498			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
499			return
500		}
501	
502		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
503		var req mergeRequest
504		dec := json.NewDecoder(r.Body)
505		if err := dec.Decode(&req); err != nil {
506			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
507			return
508		}
509		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
510			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
511			return
512		}
513	
514		if req.DeviceID == "" {
515			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
516			return
517		}
518		// baseCursor must be present and a non-negative integer (no fractions,
519		// strings, booleans or null).
520		if len(req.BaseCursor) == 0 {
521			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
522			return
523		}
524		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
525		if !ok {
526			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
527			return
528		}
529		if req.Change == nil {
530			writeError(w, http.StatusBadRequest, "change must be an object")
531			return
532		}
533		if req.Change.ID == "" {
534			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
535			return
536		}
537		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
538			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
539			return
540		}
541	
542		result, err := s.MergeChange(documentID, baseCursor, store.Change{
543			ID:       req.Change.ID,
544			DeviceID: req.DeviceID,
545			Payload:  req.Change.Payload,
546		})
547		if err != nil {
548			var conflict *store.ErrConflict
549			switch {
550			case errors.Is(err, store.ErrStaleCursor):
551				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
552				return
553			case errors.As(err, &conflict):
554				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
555				return
556			default:
557				writeError(w, http.StatusInternalServerError, "failed to merge change")
558				return
559			}
560		}
561	
562		writeJSON(w, http.StatusOK, result)
563	}
