697	// handleSetPermission grants or revokes a registered device's access to one
698	// document. Devices start authorized, so the first revoke is the first write;
699	// repeating the current state is idempotent (changed=false). A rejected
700	// request (bad content type, malformed JSON, trailing content, empty or
701	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
702	// unregistered device is a 404 JSON error.
703	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
704		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
705	
706		var req permissionRequest
707		if !decodeJSONBody(w, r, &req) {
708			return
709		}
710		if req.DeviceID == "" {
711			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
712			return
713		}
714		var authorized bool
715		switch req.Action {
716		case "grant":
717			authorized = true
718		case "revoke":
719			authorized = false
720		default:
721			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
722			return
723		}
724	
725		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
726		if err != nil {
727			if errors.Is(err, store.ErrDeviceNotFound) {
728				writeError(w, http.StatusNotFound, "device not found")
729				return
730			}
731			writeError(w, http.StatusInternalServerError, "failed to update permission")
732			return
733		}
734	
735		writeJSON(w, http.StatusOK, map[string]any{
736			"deviceId":   req.DeviceID,
737			"authorized": authorized,
738			"changed":    changed,
739		})
740	}
