742	// parseCursorPath reports whether raw is a decimal non-negative integer and
743	// returns its value. Signs, fractions and other adornments are rejected.
744	func parseCursorPath(raw string) (int64, bool) {
745		if raw == "" {
746			return 0, false
747		}
748		for _, c := range raw {
749			if c < '0' || c > '9' {
750				return 0, false
751			}
752		}
753		n, err := strconv.ParseInt(raw, 10, 64)
754		if err != nil {
755			return 0, false
756		}
757		return n, true
758	}
759	
760	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
761	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
762		var n int64
763		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
764			return 0, false
765		}
766		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
767		// require the literal to contain no fraction or exponent.
768		trimmed := strings.TrimSpace(string(raw))
769		if trimmed == "" || trimmed[0] == '-' {
770			return 0, false
771		}
772		for _, c := range trimmed {
773			if c < '0' || c > '9' {
774				return 0, false
775			}
776		}
777		return n, true
778	}
779	
780	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
781	// strings, booleans, null and negative numbers are rejected.
782	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
783		n, ok := parseNonNegativeInt(raw)
784		if !ok || n < 1 {
785			return 0, false
786		}
787		return n, true
788	}
789	
790	// isJSONObject reports whether raw decodes to a JSON object (not null, an
791	// array or a scalar).
792	func isJSONObject(raw json.RawMessage) bool {
793		var m map[string]json.RawMessage
794		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
795			return false
796		}
797		return true
798	}
