817	// handleSessionChanges is the session-scoped view of the existing change log:
818	// both path identifiers must be non-empty (the empty-segment guard rejects
819	// those before routing) and the session must currently exist, after which the
820	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
821	// the session's device has been revoked permission for the document, which is
822	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
823	// read; the change log itself is untouched.
824	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
825		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
826		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
827	
828		// Malformed query parameters are a request-shape error (400) checked
829		// before the resource lookup (404), matching the snapshot GET ordering.
830		after, limit, ok := parseChangesQuery(w, r)
831		if !ok {
832			return
833		}
834	
835		deviceID, err := s.SessionDevice(sessionID)
836		if err != nil {
837			if errors.Is(err, store.ErrSessionNotFound) {
838				writeError(w, http.StatusNotFound, "session not found")
839				return
840			}
841			writeError(w, http.StatusInternalServerError, "failed to look up session")
842			return
843		}
844	
845		authorized, err := s.DocumentAuthorized(documentID, deviceID)
846		if err != nil {
847			writeError(w, http.StatusInternalServerError, "failed to look up permission")
848			return
849		}
850		if !authorized {
851			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
852			return
853		}
854	
855		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
856		if err != nil {
857			writeError(w, http.StatusInternalServerError, "failed to list changes")
858			return
859		}
860	
861		writeChangesPage(w, changes, nextCursor)
862	}
863	
864	// parseChangesQuery parses the shared after/limit pagination parameters,
865	// writing the documented 400 on an illegal value. It is shared by the
866	// document-scoped and session-scoped change listings so their query semantics
867	// cannot drift apart.
868	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
869		q := r.URL.Query()
870	
871		after = 0
872		if raw := q.Get("after"); raw != "" {
873			v, err := strconv.ParseInt(raw, 10, 64)
874			if err != nil || v < 0 {
875				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
876				return 0, 0, false
877			}
878			after = v
879		}
880	
881		limit = defaultListLimit
882		if raw := q.Get("limit"); raw != "" {
883			v, err := strconv.ParseInt(raw, 10, 64)
884			if err != nil || v < 1 || v > maxListLimit {
885				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
886				return 0, 0, false
887			}
888			limit = v
889		}
890	
891		return after, limit, true
892	}
893	
894	// writeChangesPage renders a change listing page in the shared response shape.
895	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
896		writeJSON(w, http.StatusOK, map[string]any{
897			"changes":    changes,
898			"nextCursor": nextCursor,
899		})
900	}
901	
902	func writeJSON(w http.ResponseWriter, status int, v any) {
903		w.Header().Set("Content-Type", "application/json")
904		w.WriteHeader(status)
905		_ = json.NewEncoder(w).Encode(v)
906	}
907	
908	func writeError(w http.ResponseWriter, status int, message string) {
909		writeJSON(w, status, map[string]string{"error": message})
910	}
911	
912	// handlePollChanges is the long-polling entry over the change log.
913	//
914	// Query params share the existing change-read constraints: after is a
915	// non-negative cursor (default 0) and limit is 1..1000 (default 100); waitMs
916	// is 0..30000 (default 0). Rows already past after return immediately; a known
917	// document caught up to after parks until the first new commit or the wait
918	// deadline; an unknown document returns an empty page with cursor 0 at once.
919	// The response shape is the ordinary page plus a timedOut flag; a deadline
920	// expiry echoes the caller's cursor and never advances it. A client
921	// disconnect simply stops the wait and writes nothing.
922	func handlePollChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
923		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
924	
925		after, limit, ok := parseChangesQuery(w, r)
926		if !ok {
927			return
928		}
929		q := r.URL.Query()
930		var waitMs int64
931		if raw := q.Get("waitMs"); raw != "" {
932			v, err := strconv.ParseInt(raw, 10, 64)
933			if err != nil || v < 0 || v > maxPollWaitMillis {
934				writeError(w, http.StatusBadRequest, "waitMs must be an integer between 0 and 30000")
935				return
936			}
937			waitMs = v
938		}
939	
940		changes, nextCursor, timedOut, err := s.WaitForChanges(
941			r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
942		)
943		switch {
944		case errors.Is(err, store.ErrStoreClosing):
945			writeError(w, http.StatusServiceUnavailable, "service is shutting down")
946			return
947		case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
948			// The client went away (or, with waitMs bounded, its deadline lapsed
949			// at the transport): nothing more to write and nothing was stored.
950			return
951		case err != nil:
952			writeError(w, http.StatusInternalServerError, "failed to poll changes")
953			return
954		}
955	
956		writeJSON(w, http.StatusOK, map[string]any{
957			"changes":    changes,
958			"nextCursor": nextCursor,
959			"timedOut":   timedOut,
960		})
961	}
962	
963	// handleReplay retries an offline batch against the existing change log. The
964	// request and per-element semantics mirror POST .../changes — strict
965	// application/json body, non-empty ids, no in-batch duplicates, idempotent only
966	// when deviceId and decoded payload match, otherwise 409 reporting the
967	// conflicting id — with the registration/permission layer enforced first:
968	// 404 for an unregistered device and 403 for a revoked one, neither exposing
969	// change content. The whole batch commits in one serialized transaction that
970	// shares the document's contiguous cursor space with ordinary commits.
971	func handleReplay(s *store.Store, w http.ResponseWriter, r *http.Request) {
972		documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
973	
974		var req replayRequest
975		if !decodeJSONBody(w, r, &req) {
976			return
977		}
978		if req.DeviceID == "" {
979			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
980			return
981		}
982		if req.Operations == nil {
983			writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
984			return
985		}
986		if len(req.Operations) == 0 {
987			writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
988			return
989		}
990	
991		changes := make([]store.Change, len(req.Operations))
992		seen := make(map[string]struct{}, len(req.Operations))
993		for i, op := range req.Operations {
994			if op.ID == "" {
995				writeError(w, http.StatusBadRequest, "each operation must have a non-empty string id")
996				return
997			}
998			if len(op.Payload) == 0 {
999				writeError(w, http.StatusBadRequest, "each operation must carry a JSON payload")
1000				return
1001			}
1002			if _, dup := seen[op.ID]; dup {
1003				writeError(w, http.StatusBadRequest, "duplicate operation id within batch: "+op.ID)
1004				return
1005			}
1006			seen[op.ID] = struct{}{}
1007			changes[i] = store.Change{ID: op.ID, DeviceID: req.DeviceID, Payload: op.Payload}
1008		}
1009	
1010		results, err := s.ReplayChanges(documentID, changes)
1011		if err != nil {
1012			var conflict *store.ErrConflict
1013			switch {
1014			case errors.Is(err, store.ErrDeviceNotFound):
1015				writeError(w, http.StatusNotFound, "device not found")
1016			case errors.Is(err, store.ErrPermissionDenied):
1017				writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
1018			case errors.As(err, &conflict):
1019				writeJSON(w, http.StatusConflict, map[string]string{
1020					"error":      "operation id already exists with different deviceId or payload",
1021					"conflictId": conflict.ID,
1022				})
1023			default:
1024				writeError(w, http.StatusInternalServerError, "failed to replay operations")
1025			}
1026			return
1027		}
1028	
1029		writeJSON(w, http.StatusOK, map[string]any{"results": results})
1030	}
1031

