// Wakes returns the channel signaled whenever new merged states are queued.
func (sub *CRDTSubscription) Wakes() <-chan struct{} { return sub.wakes }

// Revoked returns the channel closed if permission is revoked while live.
func (sub *CRDTSubscription) Revoked() <-chan struct{} { return sub.revoked }

// Drain removes and returns every queued merged state in commit order.
func (sub *CRDTSubscription) Drain() []CRDTState {
	sub.mu.Lock()
	defer sub.mu.Unlock()
	out := sub.pending
	sub.pending = nil
