// enqueueCRDTStateLocked appends state to every live subscription on
// documentID. The caller holds crdtMu and has just committed the transaction
// that produced state, so subscribers observe merged states in commit order.
func (s *Store) enqueueCRDTStateLocked(documentID string, state CRDTState) {
	for key, set := range s.crdtSubs {
		if key.document != documentID {
			continue
		}
		for _, sub := range set {
			sub.mu.Lock()
			sub.pending = append(sub.pending, state)
			sub.mu.Unlock()
			select {
			case sub.wakes <- struct{}{}:
			default:
			}
		}
	}
}
