func (s *Store) SubmitCRDTOps(documentID, declaredType string, ops []CRDTOp) ([]CRDTResult, error) {
	// crdtMu serializes the whole batch — commit and post-commit fan-out
	// included — against other batches and against subscription registration,
	// so subscribers observe merged states in transaction commit order.
	s.crdtMu.Lock()
	defer s.crdtMu.Unlock()

	tx, err := s.db.Begin()
	...
	// type resolution: track whether the document already had a type
	hadState := false
	switch {
	case errors.Is(err, sql.ErrNoRows):
		... insert ...
		docType = declaredType
	case err != nil:
		return nil, err
	default:
		if docType != declaredType { ... conflict ... }
		hadState = true
	}

	// Snapshot the merged value before the batch so the post-commit fan-out
	// only fires when the batch actually changed it.
	var before json.RawMessage
	if hadState {
		before, err = mergedCRDTValue(tx, documentID, docType)
		if err != nil { return nil, err }
	}

	results := ...
	switch docType { ... apply ... }

	after, err := mergedCRDTValue(tx, documentID, docType)
	if err != nil { return nil, err }

	if err := tx.Commit(); err != nil { return nil, err }

	if !hadState || !bytes.Equal(before, after) {
		s.enqueueCRDTStateLocked(documentID, CRDTState{Type: docType, Value: after})
	}
	return results, nil
}
