package server

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// handleCRDTSubscribe is the WebSocket subscription over a document's merged
// CRDT state:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/crdt/state/subscribe
//
// ...doc comment...
func handleCRDTSubscribe(s *store.Store, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")
	documentID := r.PathValue("documentId")

	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}
	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		return
	}
	serveCRDTSubscription(r, s, conn, documentID, deviceID)
}

// crdtStateFrame renders one subscription frame: byte-for-byte the body of
// GET /v1/documents/{documentID}/crdt/state — a compact single-line JSON
// object with the keys in type,value order and a trailing newline.
func crdtStateFrame(state store.CRDTState) []byte {
	raw, err := json.Marshal(map[string]any{
		"type":  state.Type,
		"value": json.RawMessage(state.Value),
	})
	if err != nil {
		return nil
	}
	return append(raw, '\n')
}
