func serveCRDTSubscription(r *http.Request, s *store.Store, conn *wsConn, documentID, deviceID string) {
	sub, initial, hasInitial, err := s.SubscribeCRDT(documentID, deviceID)
	if err != nil {
		_ = conn.Close(wsCloseInternalError, "internal error")
		_ = conn.NetClose()
		return
	}
	defer func() {
		sub.Unregister()
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				var protoErr *wsProtocolErrorString
				if errors.As(err, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only: inbound data frames are read and discarded.
		}
	}()

	checkEnd := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-sub.Revoked():
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	// The handshake is complete: push the current merged state first. A
	// document with no CRDT operations yet stays silent until the first
	// state appears.
	if hasInitial {
		if checkEnd() {
			return
		}
		if err := conn.WriteText(crdtStateFrame(initial)); err != nil {
			return
		}
	}

	for {
		select {
		case <-sub.Wakes():
		case <-sub.Revoked():
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return
		case <-clientGone:
			return
		case <-r.Context().Done():
			return
		}
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return
		}

		// Drain every queued merged state in commit order; each one is a
		// distinct merged value, pushed exactly once.
		for _, state := range sub.Drain() {
			if checkEnd() {
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}
			if err := conn.WriteText(crdtStateFrame(state)); err != nil {
				return
			}
		}
		if checkEnd() {
			return
		}
	}
}
